import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CBWbbCW8.js";const u=JSON.parse('{"title":"Cherry Studio","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/cherry-studio.md","filePath":"integrations/cherry-studio.md","lastUpdated":1784970792000}'),r={name:"integrations/cherry-studio.md"};function l(s,e,d,n,c,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="cherry-studio" tabindex="-1">Cherry Studio <a class="header-anchor" href="#cherry-studio" aria-label="Permalink to &quot;Cherry Studio&quot;">​</a></h1><p>Cherry Studio 支持添加自定义 OpenAI 兼容服务商。DouDi.ai 状态接口中也公开了 Cherry Studio 的快速配置入口，但手动配置最稳妥。</p><h2 id="手动配置" tabindex="-1">手动配置 <a class="header-anchor" href="#手动配置" aria-label="Permalink to &quot;手动配置&quot;">​</a></h2><ol><li>打开 Cherry Studio。</li><li>进入设置中的模型服务商。</li><li>添加 OpenAI Compatible 或自定义服务商。</li><li>API 地址填写：<code>https://doudi.ai/v1</code>。</li><li>API Key 填写 DouDi.ai 控制台创建的 Key。</li><li>模型名填写你的账号可用模型。</li><li>保存后点击测试。</li></ol><h2 id="推荐模型填写方式" tabindex="-1">推荐模型填写方式 <a class="header-anchor" href="#推荐模型填写方式" aria-label="Permalink to &quot;推荐模型填写方式&quot;">​</a></h2><p>如果客户端没有自动拉取模型列表，可以手动输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gpt-5.6</span></span></code></pre></div><p>也可以到<a href="/diudi-docs/guide/models-pricing">模型与价格</a>页面复制当前公开模型名。</p><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><ul><li>测试失败时，先确认 Base URL 没有多写 <code>/chat/completions</code>。</li><li>模型列表拉取失败不一定代表不能用，可以手动添加模型名。</li><li>如果聊天能发出但没有回复，查看 DouDi.ai 的 <code>Usage Logs</code> 是否有失败原因。</li></ul>',10)])])}const _=a(r,[["render",l]]);export{u as __pageData,_ as default};
